function largestBlock(heights: number[]): number {
  const n = heights.length;
  const stack: number[] = []; // indices, heights increasing from bottom to top
  let best = 0;
  for (let i = 0; i <= n; i++) {
    const h = i === n ? 0 : heights[i]; // sentinel flushes the stack
    while (stack.length && heights[stack[stack.length - 1]] >= h) {
      const top = stack.pop()!;
      const leftEdge = stack.length ? stack[stack.length - 1] : -1;
      best = Math.max(best, heights[top] * (i - leftEdge - 1));
    }
    stack.push(i);
  }
  return best;
}

